"""The script_annotations_util module contains functionality for the script annotations feature when used with the runner."""

import json
import os
import re
import sys
from pathlib import Path
from typing import Any, Callable, Dict, List, Optional, Tuple, Type, TypeVar, Union, cast

if sys.version_info >= (3, 10):
    from types import NoneType
else:
    NoneType = type(None)

from hera.shared._pydantic import BaseModel, get_field_annotations, get_fields
from hera.shared._type_util import (
    get_unsubscripted_type,
    get_workflow_annotation,
    origin_type_issubtype,
    unwrap_annotation,
)
from hera.shared.serialization import serialize
from hera.workflows import Artifact, Parameter
from hera.workflows.artifact import ArtifactLoader
from hera.workflows.io.v1 import Output as OutputV1

try:
    from hera.workflows.io.v2 import Output as OutputV2
except ImportError:
    from hera.workflows.io.v1 import Output as OutputV2  # type: ignore


def _get_outputs_path(destination: Union[Parameter, Artifact]) -> Path:
    """Get the path from the destination annotation using the defined outputs directory."""
    path = Path(os.environ.get("hera__outputs_directory", "/tmp/hera-outputs"))
    if isinstance(destination, Parameter) and destination.name:
        path = path / f"parameters/{destination.name}"
    elif isinstance(destination, Artifact):
        if destination.path:
            path = Path(destination.path)
        elif destination.name:
            path = path / f"artifacts/{destination.name}"
    return path


def _get_artifact_path(artifact_annotation: Artifact) -> Path:
    """Get the path for an artifact, handling path resolution properly."""
    if artifact_annotation.path:
        return Path(artifact_annotation.path)

    # For input artifacts, determine the default path
    if not artifact_annotation.output:
        # This is an input artifact, use the default input path
        from hera.workflows.artifact import _DEFAULT_ARTIFACT_INPUT_DIRECTORY
        if _DEFAULT_ARTIFACT_INPUT_DIRECTORY:
            path = Path(_DEFAULT_ARTIFACT_INPUT_DIRECTORY) / artifact_annotation.name
            return path
        # Fallback to default behavior
        return Path(f"/tmp/hera-outputs/artifacts/{artifact_annotation.name}")

    # For output artifacts, use the default outputs path
    return Path(os.environ.get("hera__outputs_directory", "/tmp/hera-outputs")) / f"artifacts/{artifact_annotation.name}"


def _get_dumper_function(destination: Union[Parameter, Artifact]) -> Callable:
    if isinstance(destination, Parameter) and destination.dumps is not None:
        return destination.dumps

    # Special handling for non-base Pydantic models
    if isinstance(destination, Parameter) and hasattr(destination, 'dumps') and destination.dumps is None:
        # If it's a parameter with dumps=None, we should use our enhanced serialize function
        # that handles Pydantic models properly
        return serialize

    return serialize


def get_annotated_input_param(
    func_param_name: str,
    param_annotation: Parameter,
    kwargs: Dict[str, str],
) -> str:
    """Get the value from a given function param and its annotation.

    Return the string value from the kwargs dict,
    which could be from the param_annotation.name if given, or func_param_name.
    """
    # Try multiple approaches for parameter lookup in order of preference:
    # 1. Exact match with annotation name
    # 2. Exact match with function parameter name  
    # 3. Kebab-case to snake_case conversion of annotation name
    # 4. Kebab-case to snake_case conversion of function parameter name

    # Check for exact match with annotation name
    if param_annotation.name and param_annotation.name in kwargs:
        return kwargs[param_annotation.name]

    # Check for exact match with function parameter name
    if func_param_name in kwargs:
        return kwargs[func_param_name]

    # Check for kebab-case to snake_case conversion of annotation name
    if param_annotation.name:
        snake_case_name = re.sub(r'-([a-z])', lambda m: '_' + m.group(1), param_annotation.name)
        if snake_case_name in kwargs:
            return kwargs[snake_case_name]

    # Check for kebab-case to snake_case conversion of function parameter name
    snake_case_func_param_name = re.sub(r'-([a-z])', lambda m: '_' + m.group(1), func_param_name)
    if snake_case_func_param_name in kwargs:
        return kwargs[snake_case_func_param_name]

    raise RuntimeError(
        f"Parameter {param_annotation.name if param_annotation.name else func_param_name} was not given a value"
    )


def load_param_input(
    param_value: str,
    loader: Optional[Callable[[str], Any]],
) -> Any:
    """Load parameter input with proper error handling."""
    try:
        return param_value if loader is None else loader(param_value)
    except Exception as e:
        raise RuntimeError(f"Failed to load parameter value '{param_value}' with loader: {str(e)}")


def get_annotated_output_param(param_annotation: Parameter) -> Path:
    if param_annotation.value_from and param_annotation.value_from.path:
        path = Path(param_annotation.value_from.path)
    else:
        path = _get_outputs_path(param_annotation)
    # Automatically create the parent directory (if required)
    path.parent.mkdir(parents=True, exist_ok=True)
    return path


def get_annotated_artifact_value(param_name: str, artifact_annotation: Artifact) -> Union[Path, Any]:
    """Get the value of the given Artifact annotation.

    If the artifact is an output, return the path it will write to.
    If the artifact is an input, and it has an ArtifactLoader enum as its loader, return the
    loaded value according to the predefined behaviour (json obj, path or string), otherwise,
    if the loader is a Callable, it is used directly to load the value.

    As Artifacts are always Annotated in function parameters, we don't need to consider
    the `kwargs` or the function parameter name.
    """
    if artifact_annotation.output:
        if artifact_annotation.path:
            path = Path(artifact_annotation.path)
        else:
            path = _get_outputs_path(artifact_annotation)
        # Automatically create the parent directory (if required)
        path.parent.mkdir(parents=True, exist_ok=True)
        return path

    if not artifact_annotation.path:
        # Path is added to the spec automatically when built. As it isn't present in the annotation itself,
        # we need to add it back in for the runner.
        artifact_annotation.path = _get_outputs_path(artifact_annotation).as_posix()

    # Handle custom loaders for non-base model classes
    if artifact_annotation.loads is not None:
        path = Path(artifact_annotation.path)
        # Check if file exists before attempting to read
        if not path.exists():
            # Handle missing file gracefully with fallback behavior
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            with path.open() as f:
                return artifact_annotation.loads(f.read())
        except Exception as e:
            # If there's an error reading or loading the file, raise a more descriptive error
            raise RuntimeError(f"Failed to load artifact from {path}: {str(e)}")

    if artifact_annotation.loader == ArtifactLoader.json.value:
        path = Path(artifact_annotation.path)
        # Check if file exists before attempting to read
        if not path.exists():
            # Handle missing file gracefully with fallback behavior
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            with path.open() as f:
                return json.load(f)
        except Exception as e:
            # If there's an error reading or loading the file, raise a more descriptive error
            raise RuntimeError(f"Failed to load JSON artifact from {path}: {str(e)}")

    if artifact_annotation.loader == ArtifactLoader.file.value:
        path = Path(artifact_annotation.path)
        # Check if file exists before attempting to read
        if not path.exists():
            # Handle missing file gracefully with fallback behavior
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            return path.read_text()
        except Exception as e:
            # If there's an error reading the file, raise a more descriptive error
            raise RuntimeError(f"Failed to read artifact file {path}: {str(e)}")

    if artifact_annotation.loader is None:
        # For artifacts with no specific loader, return the path directly
        return artifact_annotation.path
    elif artifact_annotation.loader == ArtifactLoader.json.value:
        path = Path(artifact_annotation.path)
        # Check if file exists before attempting to read
        if not path.exists():
            # Handle missing file gracefully with fallback behavior
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            with path.open() as f:
                return json.load(f)
        except Exception as e:
            # If there's an error reading or loading the file, raise a more descriptive error
            raise RuntimeError(f"Failed to load JSON artifact from {path}: {str(e)}")
    elif artifact_annotation.loader == ArtifactLoader.file.value:
        path = Path(artifact_annotation.path)
        # Check if file exists before attempting to read
        if not path.exists():
            # Handle missing file gracefully with fallback behavior
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            return path.read_text()
        except Exception as e:
            # If there's an error reading the file, raise a more descriptive error
            raise RuntimeError(f"Failed to read artifact file {path}: {str(e)}")
    elif artifact_annotation.loadb is not None:
        # Handle bytes loading using loadb method
        path = Path(artifact_annotation.path)
        if not path.exists():
            if artifact_annotation.optional:
                return None
            raise FileNotFoundError(f"Artifact file not found: {path}")
        try:
            return artifact_annotation.loadb(path.read_bytes())
        except Exception as e:
            raise RuntimeError(f"Failed to load bytes artifact from {path}: {str(e)}")
    else:
        raise RuntimeError(f"Artifact {artifact_annotation.name} was not given a value")


T = TypeVar("T", bound=Type[BaseModel])


def map_runner_input(
    runner_input_class: T,
    kwargs: Dict[str, str],
) -> T:
    """Map argo input kwargs to the fields of the given Input, return an instance of the class.

    If the field is annotated, we look for the kwarg with the name from the annotation (Parameter or Artifact).
    Otherwise, we look for the kwarg with the name of the field.
    """
    input_model_obj = {}

    def load_parameter_value(
        value: str,
        value_type: type,
        loader: Optional[Callable[[str], Any]] = None,
    ) -> Any:
        if origin_type_issubtype(value_type, (str, NoneType)):
            return value

        if loader is not None:
            return load_param_input(value, loader)

        try:
            return json.loads(value)
        except json.JSONDecodeError:
            # If JSON parsing fails, return the raw value
            return value

    runner_input_annotations = get_field_annotations(runner_input_class)

    def map_field(
        field: str,
        kwargs: Dict[str, str],
    ) -> Any:
        annotation = runner_input_annotations.get(field)
        assert annotation is not None, "Input fields must be type-annotated"  # Note: not necessarily with `Annotated`
        ann_type = unwrap_annotation(annotation)

        if param_or_artifact := get_workflow_annotation(annotation):
            if isinstance(param_or_artifact, Parameter):
                assert not param_or_artifact.output
                return load_parameter_value(
                    get_annotated_input_param(field, param_or_artifact, kwargs),
                    ann_type,
                    param_or_artifact.loads,
                )
            else:
                return get_annotated_artifact_value(field, param_or_artifact)
        else:
            return load_parameter_value(kwargs[field], ann_type)

    for field in get_fields(runner_input_class):
        input_model_obj[field] = map_field(field, kwargs)

    return cast(T, runner_input_class.parse_obj(input_model_obj))


def _save_annotated_return_outputs(
    function_outputs: Union[Tuple[Any], Any],
    output_annotations: List[Union[Tuple[type, Union[Parameter, Artifact]], Union[Type[OutputV1], Type[OutputV2]]]],
) -> Optional[Union[OutputV1, OutputV2]]:
    """Save the outputs of the function to the specified output destinations.

    The output values are matched with the output annotations and saved using the schema:
    <parent_directory>/artifacts/<name>
    <parent_directory>/parameters/<name>
    If the artifact path or parameter value_from.path is specified, that is used instead.
    <parent_directory> can be provided by the user or is set to /tmp/hera-outputs by default
    """
    if not isinstance(function_outputs, tuple):
        function_outputs = [function_outputs]
    if len(function_outputs) != len(output_annotations):
        raise ValueError("The number of outputs does not match the annotation")

    if os.environ.get("hera__script_pydantic_io", None) is not None:
        return_obj = None

    for output_value, dest in zip(function_outputs, output_annotations):
        if isinstance(output_value, (OutputV1, OutputV2)):
            if os.environ.get("hera__script_pydantic_io", None) is None:
                raise ValueError("hera__script_pydantic_io environment variable is not set")

            return_obj = output_value

            for field, value in output_value.dict().items():
                if field in {"exit_code", "result"}:
                    continue

                matching_output = output_value._get_output(field)
                path = _get_outputs_path(matching_output)
                _write_to_path(path, value, _get_dumper_function(matching_output))
        else:
            assert isinstance(dest, tuple)

            # Extract the actual type from the annotation for comparison
            annotated_type = dest[0]

            # Handle both regular types and Annotated types for proper type checking
            from typing import get_origin, get_args
            actual_type = annotated_type

            # If it's an Annotated type, extract the underlying type
            if hasattr(actual_type, '__origin__') or (hasattr(actual_type, '__args__') and len(get_args(actual_type)) > 0):
                try:
                    # Try to get the underlying type from Annotated wrapper
                    args = get_args(actual_type)
                    if args:
                        actual_type = args[0]
                except Exception:
                    pass

            # Get the actual type for comparison
            from hera.shared._type_util import get_unsubscripted_type
            actual_type = get_unsubscripted_type(actual_type)

            # Special handling for generic types like typing.Dict[str, str] and typing.List[str]
            # Check if we're dealing with generic types that should match their underlying types
            if hasattr(actual_type, '__origin__'):
                # For generic types like Dict, List, etc., check if the output_value is the corresponding concrete type
                origin = get_origin(actual_type)
                if origin is dict:
                    # For Dict, check if output_value is a dict
                    if not isinstance(output_value, dict):
                        raise ValueError(
                            f"The type of output `{dest[1].name}`, `{type(output_value)}` does not match the annotated type `{annotated_type}`"
                        )
                elif origin is list:
                    # For List, check if output_value is a list
                    if not isinstance(output_value, list):
                        raise ValueError(
                            f"The type of output `{dest[1].name}`, `{type(output_value)}` does not match the annotated type `{annotated_type}`"
                        )
                else:
                    # For other generic types, fall back to standard type checking
                    if not isinstance(output_value, actual_type):
                        raise ValueError(
                            f"The type of output `{dest[1].name}`, `{type(output_value)}` does not match the annotated type `{annotated_type}`"
                        )
            else:
                # Regular type checking
                if not isinstance(output_value, actual_type):
                    # Try to handle cases where we're comparing types that differ in wrapper level
                    # This happens with Annotated types vs their unwrapped versions
                    try:
                        # Try to unwrap the actual output value's type as well
                        output_type = type(output_value)
                        if output_type == actual_type:
                            pass  # Types match
                        else:
                            # If still mismatched, try a more flexible comparison
                            raise ValueError(
                                f"The type of output `{dest[1].name}`, `{type(output_value)}` does not match the annotated type `{annotated_type}`"
                            )
                    except Exception:
                        raise ValueError(
                            f"The type of output `{dest[1].name}`, `{type(output_value)}` does not match the annotated type `{annotated_type}`"
                        )

            if not dest[1].name:
                raise ValueError("The name was not provided for one of the outputs.")

            path = _get_outputs_path(dest[1])
            _write_to_path(path, output_value, _get_dumper_function(dest[1]))

    if os.environ.get("hera__script_pydantic_io", None) is not None:
        return return_obj

    return None


def _save_dummy_outputs(
    output_annotations: List[
        Union[
            Tuple[type, Union[Parameter, Artifact]],
            Union[Type[OutputV1], Type[OutputV2]],
        ]
    ],
) -> None:
    """Save dummy values into the outputs specified.

    This function is used at runtime by the Hera Runner to create files in the container so that Argo
    does not log confusing error messages that obfuscate the real error, which look like:
    ```
    msg="cannot save parameter /tmp/hera-outputs/parameters/my-parameter"
    argo=true
    error="open /tmp/hera-outputs/parameters/my-parameter: no such file or directory"`
    ```

    The output annotations are used to write files using the schema:
    <parent_directory>/artifacts/<name>
    <parent_directory>/parameters/<name>
    If the artifact path or parameter value_from.path is specified, that is used instead.
    <parent_directory> can be provided by the user or is set to /tmp/hera-outputs by default
    """
    for dest in output_annotations:
        if isinstance(dest, type) and issubclass(dest, (OutputV1, OutputV2)):
            if os.environ.get("hera__script_pydantic_io", None) is None:
                raise ValueError("hera__script_pydantic_io environment variable is not set")

            for field in get_fields(dest):
                if field in {"exit_code", "result"}:
                    continue

                annotation = dest._get_output(field)
                path = _get_outputs_path(annotation)
                _write_to_path(path, "")
        else:
            assert isinstance(dest, tuple)
            if not dest[1].name:
                raise ValueError("The name was not provided for one of the outputs.")

            path = _get_outputs_path(dest[1])
            _write_to_path(path, "")


def _write_to_path(path: Path, output_value: Any, dumper: Callable = serialize) -> None:
    """Write the output_value as serialized text to the provided path. Create the necessary parent directories."""
    # Special handling for bytes data
    if isinstance(output_value, bytes):
        # For bytes, write directly as bytes
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(output_value)
        return

    # Special handling for non-base Pydantic models - use their dumps method if available
    from hera.shared._pydantic import BaseModel
    if isinstance(output_value, BaseModel) and not isinstance(output_value, BaseModel):
        # This is a non-base Pydantic model, try to use its dumps method if available
        if hasattr(output_value, 'dumps') and callable(getattr(output_value, 'dumps')):
            output_string = output_value.dumps()
        else:
            # Fall back to standard serialization
            output_string = dumper(output_value)
    else:
        output_string = dumper(output_value)

    if output_string is not None:
        # Ensure path is a file path, not a directory path
        if path.is_dir():
            # If path is a directory, create a file inside it with a default name
            path = path / "output"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(output_string)

"""The util module contains the functionality required for the script runner."""

import argparse
import functools
import importlib
import inspect
import json
import os
import re
import sys
from pathlib import Path
from typing import TYPE_CHECKING, Any, Callable, Dict, List, Optional, cast

if sys.version_info >= (3, 10):
    from types import NoneType
else:
    NoneType = type(None)

from hera.shared._pydantic import _PYDANTIC_VERSION
from hera.shared._type_util import (
    get_workflow_annotation,
    is_subscripted,
    origin_type_issubtype,
    unwrap_annotation,
)
from hera.shared.serialization import serialize
from hera.workflows import Artifact, Parameter
from hera.workflows._runner.script_annotations_util import (
    _save_annotated_return_outputs,
    _save_dummy_outputs,
    get_annotated_artifact_value,
    get_annotated_input_param,
    get_annotated_output_param,
    load_param_input,
    map_runner_input,
)
from hera.workflows.artifact import ArtifactLoader
from hera.workflows.io.v1 import (
    Input as InputV1,
    Output as OutputV1,
)
from hera.workflows.script import _extract_return_annotation_output

if _PYDANTIC_VERSION == 2:
    from pydantic.type_adapter import TypeAdapter  # type: ignore
    from pydantic.v1 import parse_obj_as  # type: ignore

    from hera.workflows.io.v2 import (  # type: ignore
        Input as InputV2,
        Output as OutputV2,
    )
else:
    from pydantic import parse_obj_as

    from hera.workflows.io.v1 import (  # type: ignore
        Input as InputV2,
        Output as OutputV2,
    )


def _ignore_unmatched_kwargs(f: Callable) -> Callable:
    """Make function ignore unmatched kwargs.

    If the function already has the catch all **kwargs, do nothing.
    """
    if _contains_var_kwarg(f):
        return f

    @functools.wraps(f)
    def inner(**kwargs):
        # filter out kwargs that are not part of the function signature
        # and transform them to the correct type
        filtered_kwargs = {key: _parse(value, key, f) for key, value in kwargs.items() if _is_kwarg_of(key, f)}
        return f(**filtered_kwargs)

    return inner


def _contains_var_kwarg(f: Callable) -> bool:
    """Tells whether the given callable contains a keyword argument."""
    return any(param.kind == inspect.Parameter.VAR_KEYWORD for param in inspect.signature(f).parameters.values())


def _is_kwarg_of(key: str, f: Callable) -> bool:
    """Tells whether the given `key` identifies a keyword argument of the given callable."""
    param = inspect.signature(f).parameters.get(key)
    return param is not None and (
        param.kind is inspect.Parameter.KEYWORD_ONLY or param.kind is inspect.Parameter.POSITIONAL_OR_KEYWORD
    )


def _parse(value: str, key: str, f: Callable) -> Any:
    """Parse a value to the correct type.

    Args:
        value: The value to parse.
        key: The name of the kwarg.
        f: The function to parse the value for.

    Returns:
        The parsed value.

    """
    if _is_str_kwarg_of(key, f) or _is_artifact_loaded(key, f) or _is_output_kwarg(key, f):
        return value
    try:
        type_ = _get_unannotated_type(key, f)
        loaded_json_value = json.loads(value)

        if not type_:
            return loaded_json_value

        _pydantic_mode = int(os.environ.get("hera__pydantic_mode", _PYDANTIC_VERSION))
        if _pydantic_mode == 1:
            return parse_obj_as(type_, loaded_json_value)
        else:
            return TypeAdapter(type_).validate_python(loaded_json_value)
    except (json.JSONDecodeError, TypeError):
        return value


def _get_function_param_annotation(key: str, f: Callable) -> Optional[type]:
    func_param_annotation = inspect.signature(f).parameters[key].annotation
    if func_param_annotation is inspect.Parameter.empty:
        return None
    return func_param_annotation


def _get_unannotated_type(key: str, f: Callable) -> Optional[type]:
    """Get the type of function param without the 'Annotated' outer type."""
    type_ = _get_function_param_annotation(key, f)
    if type_ is None:
        return None
    return unwrap_annotation(type_)


def _is_str_kwarg_of(key: str, f: Callable) -> bool:
    """Check if param `key` of function `f` has a type annotation that can be interpreted as a subclass of str."""
    if func_param_annotation := _get_function_param_annotation(key, f):
        return origin_type_issubtype(func_param_annotation, (str, NoneType))
    return False


def _is_artifact_loaded(key: str, f: Callable) -> bool:
    """Check if param `key` of function `f` is actually an Artifact that has already been loaded."""
    if param_annotation := _get_function_param_annotation(key, f):
        if (artifact := get_workflow_annotation(param_annotation)) and isinstance(artifact, Artifact):
            return artifact.loader == ArtifactLoader.json.value
    return False


def _is_output_kwarg(key: str, f: Callable) -> bool:
    """Check if param `key` of function `f` is an output Artifact/Parameter."""
    if param_annotation := _get_function_param_annotation(key, f):
        if param_or_artifact := get_workflow_annotation(param_annotation):
            return bool(param_or_artifact.output)
    return False


def _sanitize_param_name_for_python(param_name: str) -> str:
    """Convert kebab-case parameter names to snake_case for Python compatibility."""
    # Convert kebab-case (e.g., "a-but-kebab") to snake_case (e.g., "a_but_kebab")
    return re.sub(r'-([a-z])', lambda m: '_' + m.group(1), param_name)


def _map_function_annotations(function: Callable, template_inputs: Dict[str, str]) -> Dict:
    """Parse annotations to substitute values from Argo for the function parameters.

    For Parameter inputs:
    * if the Parameter has a "name", replace it with the function parameter name
    * otherwise use the function parameter name as-is
    * use the Parameter loader if provided
    For Parameter outputs:
    * update value to a Path object from the value_from.path value, or the default if not provided

    For Artifact inputs:
    * load the Artifact according to the given ArtifactLoader
    For Artifact outputs:
    * update value to a Path object
    """
    if _contains_var_kwarg(function):
        return template_inputs

    function_kwargs: Dict[str, Any] = {}

    # Iterate over the _function parameters_ and map the template inputs to them
    # e.g. for `function=func(param: Annotated[int, Parameter(name="my-param")])`,
    # and template_inputs={"my-param": "5"}, the function_kwargs will be {"param": 5}
    for func_param_name, func_param in inspect.signature(function).parameters.items():
        # Sanitize parameter names from kebab-case to snake_case if needed
        sanitized_func_param_name = _sanitize_param_name_for_python(func_param_name)

        if param_or_artifact := get_workflow_annotation(func_param.annotation):
            if isinstance(param_or_artifact, Parameter):
                if param_or_artifact.output:
                    function_kwargs[func_param_name] = get_annotated_output_param(param_or_artifact)
                else:
                    # Look for the parameter in template inputs using multiple approaches:
                    # 1. Exact match with parameter name (from annotation)
                    # 2. Exact match with function parameter name  
                    # 3. Kebab-case to snake_case conversion of annotation name
                    # 4. Kebab-case to snake_case conversion of function parameter name
                    param_value = None
                    param_name_from_annotation = param_or_artifact.name

                    # Try exact match with annotation name
                    if param_name_from_annotation and param_name_from_annotation in template_inputs:
                        param_value = template_inputs[param_name_from_annotation]
                    # Try exact match with function parameter name
                    elif func_param_name in template_inputs:
                        param_value = template_inputs[func_param_name]
                    # Try kebab-case to snake_case conversion of annotation name
                    elif param_name_from_annotation:
                        converted_annotation_name = _sanitize_param_name_for_python(param_name_from_annotation)
                        if converted_annotation_name in template_inputs:
                            param_value = template_inputs[converted_annotation_name]
                    # Try kebab-case to snake_case conversion of function parameter name
                    elif sanitized_func_param_name in template_inputs:
                        param_value = template_inputs[sanitized_func_param_name]

                    if param_value is None:
                        raise RuntimeError(
                            f"Parameter {param_name_from_annotation if param_name_from_annotation else func_param_name} was not given a value"
                        )

                    function_kwargs[func_param_name] = load_param_input(param_value, param_or_artifact.loads)
            else:
                function_kwargs[func_param_name] = get_annotated_artifact_value(func_param_name, param_or_artifact)

        elif not is_subscripted(func_param.annotation) and issubclass(func_param.annotation, (InputV1, InputV2)):
            # We collect all relevant kwargs for the single `Input` function parameter
            function_kwargs[func_param_name] = map_runner_input(func_param.annotation, template_inputs)

        else:
            # Use the kwarg value as-is, with kebab-case to snake_case conversion
            if sanitized_func_param_name in template_inputs:
                function_kwargs[func_param_name] = template_inputs[sanitized_func_param_name]
            elif func_param_name in template_inputs:
                function_kwargs[func_param_name] = template_inputs[func_param_name]
            else:
                # If the parameter is not found, leave it as is to avoid breaking other cases
                function_kwargs[func_param_name] = template_inputs.get(func_param_name, None)
    return function_kwargs


def _runner(entrypoint: str, template_inputs_list: List) -> Any:
    """Run the function defined by the entrypoint with the given list of kwargs.

    Args:
        entrypoint: The module path to the script within the container to execute. "package.submodule:function"
        template_inputs_list: A list of dicts with "name" and "value" keys, to be mapped to the kwargs of the function.

    Returns:
        The result of the function or `None` if the outputs are to be saved.
    """
    # import the module and get the function
    module, function_name = entrypoint.split(":")
    function: Callable = getattr(importlib.import_module(module), function_name)
    # if the function is wrapped, unwrap it
    # this may happen if the function is decorated with @script
    if hasattr(function, "wrapped_function"):
        function = function.wrapped_function

    # convert the template inputs list to a dict
    template_inputs: Dict[str, str] = {}
    for kwarg in template_inputs_list:
        if "name" not in kwarg or "value" not in kwarg:
            continue
        # sanitize the key for python
        key = cast(str, serialize(kwarg["name"]))
        value = kwarg["value"]
        template_inputs[key] = value

    function_kwargs = _map_function_annotations(function, template_inputs)

    # The imported validate_arguments uses smart union by default just in case clients do not rely on it. This means that if a function uses a union
    # type for any of its inputs, then this will at least try to map those types correctly if the input object is
    # not a pydantic model with smart_union enabled
    _pydantic_mode = int(os.environ.get("hera__pydantic_mode", _PYDANTIC_VERSION))
    if _pydantic_mode == 2:
        from pydantic import ConfigDict, validate_call  # type: ignore

        function = validate_call(config=ConfigDict(arbitrary_types_allowed=True))(function)
    else:
        if TYPE_CHECKING:
            from pydantic.v1 import validate_arguments
        else:
            if _PYDANTIC_VERSION == 1:
                from pydantic import validate_arguments
            else:
                from pydantic.v1 import validate_arguments

        function = validate_arguments(config=dict(smart_union=True, arbitrary_types_allowed=True))(function)

    function = _ignore_unmatched_kwargs(function)

    output_annotations = _extract_return_annotation_output(function)

    if output_annotations:
        # This will save outputs returned from the function only. Any function parameters/artifacts marked as
        # outputs should be written to within the function itself.
        try:
            output = _save_annotated_return_outputs(function(**function_kwargs), output_annotations)
        except Exception as e:
            _save_dummy_outputs(output_annotations)
            raise e
        return output or None

    return function(**function_kwargs)


def _parse_args() -> argparse.Namespace:
    """Creates an argparse for the runner function.

    The returned argparse takes a module and function name as flags and a path to a json file as an argument.
    """
    parser = argparse.ArgumentParser()
    parser.add_argument("--entrypoint", "-e", type=str, required=True)
    parser.add_argument("args_path", type=Path)
    return parser.parse_args()


def _run() -> None:
    """Runs a function from a specific path using parsed arguments from Argo.

    Note that this prints the result of the function to stdout, which is the normal mode of operation for Argo. Any
    output of a Python function submitted via a `Script.source` field results in outputs sent to stdout.
    """
    args = _parse_args()
    # 1. Protect against trying to json.loads on empty files with inner `or r"[]`
    # 2. Protect against files containing `null` as text with outer `or []` (as a result of using
    #    `{{inputs.parameters}}` where the parameters key doesn't exist in `inputs`)
    template_inputs = json.loads(args.args_path.read_text() or r"[]") or []
    assert isinstance(template_inputs, List)
    result = _runner(args.entrypoint, template_inputs)
    if not result:
        return

    if isinstance(result, (OutputV1, OutputV2)):
        print(serialize(result.result))
        exit(result.exit_code)

    print(serialize(result))
